      es: ["Antigua capital (hasta 1823)", "Centro religioso", "Fundada: 1563", "Altitud: 1435 m"],
      pt: ["Antiga capital (até 1823)", "Centro religioso", "Fundada: 1563", "Altitude: 1435 m"],
      fr: ["Ancienne capitale (jusqu'en 1823)", "Centre religieux", "Fondée en 1563", "Altitude : 1435 m"],
